// What the person sees of the reference's creative intelligence: the New Content panel and the Anatomy additions, rendered from the server's REAL record for reference 5131 (generated by the backend test fixtures).
import { describe, expect, it } from 'vitest'
import { renderToStaticMarkup } from 'react-dom/server'
import { readFileSync } from 'node:fs'
import rec from './__fixtures__/ref5131.creative-intelligence.json'
import anFx from './__fixtures__/ref5131.anatomy-with-intelligence.json'
import type { Anatomy } from '../../types/deconstructor'
import IntelligencePanel from './IntelligencePanel'
import { evidenceSummary, hookSummary, INTELLIGENCE_HEADING, REUSE_NOT_COPY, typeLabel, type CreativeIntelligence } from './intelligence'
import { AnatomyStage, IntentStage } from './stages'
import { anatomyOverview } from './viewModel'
import { emptyIntentForm } from './intentForm'

const intel = () => JSON.parse(JSON.stringify(rec)) as CreativeIntelligence
const anatomy = () => JSON.parse(JSON.stringify(anFx)) as Anatomy
const panel = (over: Partial<Parameters<typeof IntelligencePanel>[0]> = {}) => renderToStaticMarkup(<IntelligencePanel status="ready" intel={intel()} {...over} />)

describe('New Content: what this reference teaches', () => {
  it('states the reuse-not-copy rule and that nothing about audiences is claimed', () => {
    const h = panel()
    expect(h).toContain(INTELLIGENCE_HEADING)
    expect(h).toContain(REUSE_NOT_COPY)
    expect(h).toContain('describes apparent design only; nothing says how any audience responded')
    expect(h).toContain('Audience effects: not established.')
  })

  it('shows how the opening works as a combination of channels, with reliability and how the hook types relate', () => {
    const h = panel()
    expect(h).toContain('How the opening works')
    expect(h).toContain('Bold claim + Demonstration')
    for (const c of ['Spoken words (unverified)', 'On-screen text', 'Picture', 'Editing and framing']) expect(h).toContain(c)
    expect(h).toContain('the hook is the combination')
    expect(h).toContain('not alternatives')
    expect(h).toContain('AI interpretation of apparent design, not an effect on viewers')
  })

  it('shows the progression as read from the frames and names the section that has no reading', () => {
    const h = panel()
    expect(h).toContain('Opening / hook (section 1) → Demonstration (section 2) → Human or emotional shift (section 4)')
    expect(h).toContain('read from the frames by an AI; inferred')
    expect(h).toContain('1 of 4 sections have no visual reading')
  })

  it('gives each mechanism its purpose, principle, evidence with timestamps, weak-evidence warning and conditions', () => {
    const h = panel()
    for (const id of ['M01', 'M02', 'M03']) expect(h).toContain(`data-testid="intel-mechanism-${id}"`)
    expect(h).toContain('M01 · Hook curiosity')
    expect(h).toContain('Principle to reuse: </span>Open on a clean shot of the subject itself')
    expect(h).toContain('Seen in section 1 (0s–2s): 2 picture items, 1 spoken or sound item (1 unverified).')
    expect(h).toContain('Weak evidence: the speech behind this is unverified.')
    expect(h).toContain('May apply when')
    expect(h).toContain('Avoid when')
    expect(h).toContain('How to adapt it to your business')
    expect(h).toContain('Never copy')
    expect(h).toContain('Specific packaging text shown in the opening shot.')
    expect(h).toContain('taxonomy rule')                                                                      // the guidance says where it comes from
    expect(h).toContain('AI interpretation')
  })

  it('lists where the evidence disagrees instead of hiding it, and what the structure analysis could not establish', () => {
    const h = panel()
    expect(h).toContain('Where the evidence disagrees or is weak')
    expect(h).toContain('spoken wording')
    expect(h).toContain('What the scene and story-beat analysis could not establish')
  })

  it('shows a disagreement that affects several sections once, with its sections and how many further notes exist', () => {
    const h = panel()
    const keys = intel().contradictions.map(c => `${c.topic}|${c.status}`)
    expect(new Set(keys).size).toBe(keys.length)
    expect(h.split('<strong>spoken wording</strong>').length - 1).toBe(1)
    expect(h).toContain('+1 more note; sections 1, 2, 3, 4')
    expect(h).toContain('+2 more notes; sections 2, 3, 4')
  })

  it('handles each status honestly and never shows a mechanism it does not have', () => {
    const notRun = { ...intel(), status: 'mechanisms_not_run' as const, mechanisms: [] }
    const h = panel({ intel: notRun })
    expect(h).toContain('have not been derived yet')
    expect(h).not.toContain('data-testid="intelligence-mechanisms"')
    expect(h).toContain('data-testid="intelligence-hook"')                                                  // the rest is still shown
    expect(panel({ intel: { ...intel(), status: 'mechanisms_stale' } })).toContain('out of date')
    expect(panel({ status: 'loading', intel: null })).toContain('Reading the reference’s analysis')
    expect(panel({ status: 'error', intel: null, error: 'boom' })).toContain('You can still describe your new content below.')
  })

  it('is part of the New Content step, above the form', () => {
    const h = renderToStaticMarkup(<IntentStage form={emptyIntentForm()} errors={{}} set={() => {}} mechanismsReady busy={null} onBuild={() => {}} hasExistingBlueprint={false} intelligencePanel={<IntelligencePanel status="ready" intel={intel()} />} />)
    expect(h.indexOf('intelligence-panel')).toBeGreaterThan(-1)
    expect(h.indexOf('intelligence-panel')).toBeLessThan(h.indexOf('Product, service or topic'))
  })
})

describe('view model', () => {
  it('summarises evidence, the opening and type labels in plain words', () => {
    const m = intel().mechanisms[0]
    expect(evidenceSummary(m)).toBe('section 1 (0s–2s): 2 picture items, 1 spoken or sound item (1 unverified)')
    expect(hookSummary(intel().hook!)).toBe('Bold claim + Demonstration · 0s–2s')
    expect(typeLabel({ type: 'other', other_label: 'Mirrored framing' })).toBe('Mirrored framing')
    expect(typeLabel({ type: 'emotional_progression', other_label: null })).toBe('Emotional progression')
  })
})

describe('Anatomy: the opening, the story and what is not established', () => {
  it('shows the opening profile, the progression and the structure uncertainty', () => {
    const a = anatomy()
    const ov = anatomyOverview(a)
    expect(ov.opening?.summary).toContain('Bold claim + Demonstration')
    expect(ov.opening?.channels).toContain('Spoken words (unverified)')
    expect(ov.progression).toContain('Opening / hook (section 1)')
    expect(ov.structureNotes.join(' ')).toContain('left undecided')
    const h = renderToStaticMarkup(<AnatomyStage anatomy={{ data: a, loading: false, error: null, missing: false }} />)
    expect(h).toContain('data-testid="anatomy-creative-structure"')
    expect(h).toContain('How the opening works')
    expect(h).toContain('How the story progresses')
    expect(h).toContain('What the scene and story-beat analysis could not establish')
    expect(h).toContain('None of the 7 story-beat boundary candidates was accepted')
  })

  it('a reference with no derived views shows none of it', () => {
    const a = anatomy()
    delete (a.video as Record<string, unknown>).hook_profile; delete (a.video as Record<string, unknown>).structure; delete (a.video as Record<string, unknown>).narrative
    const h = renderToStaticMarkup(<AnatomyStage anatomy={{ data: a, loading: false, error: null, missing: false }} />)
    expect(h).not.toContain('anatomy-creative-structure')
  })
})

describe('wiring', () => {
  it('the page loads the record with the analysis and passes it to New Content; the hook refreshes it after mechanisms are derived', () => {
    const page = readFileSync(new URL('./DeconstructorPage.tsx', import.meta.url), 'utf8'), hook = readFileSync(new URL('./useDeconstructor.ts', import.meta.url), 'utf8')
    expect(page).toContain('intelligencePanel={<IntelligencePanel')
    expect(hook).toContain('deconstructorApi.creativeIntelligence(id)')
    expect(hook).toContain('creativeIntelligence(referenceVideoId)')
  })
})
